import crypto from 'crypto';
/**
 * Generate a cryptographically random PKCE code verifier
 *
 * Creates a high-entropy random string suitable for use as an OAuth 2.0 PKCE code verifier.
 * The verifier must be 43-128 characters and use only [A-Z, a-z, 0-9, -, ., _, ~].
 *
 * @returns Random code verifier string (43 characters from 32 random bytes)
 * @see https://datatracker.ietf.org/doc/html/rfc7636#section-4.1
 */ export function generateCodeVerifier() {
    // Generate 32 random bytes (256 bits of entropy)
    // This will produce a 43-character base64url string
    const buffer = crypto.randomBytes(32);
    return base64UrlEncode(buffer);
}
/**
 * Generate code challenge from verifier using S256 method
 *
 * Creates a SHA256 hash of the code verifier and encodes it in base64url format.
 * Formula: challenge = BASE64URL(SHA256(ASCII(code_verifier)))
 *
 * @param verifier - The code verifier to hash
 * @returns Code challenge string (43 characters)
 * @see https://datatracker.ietf.org/doc/html/rfc7636#section-4.2
 */ export function generateCodeChallenge(verifier) {
    const hash = crypto.createHash('sha256').update(verifier).digest();
    return base64UrlEncode(hash);
}
/**
 * Generate complete PKCE pair for OAuth flow
 *
 * Creates both a code verifier and its corresponding code challenge.
 * Use this at the start of an OAuth flow:
 * 1. Generate pair
 * 2. Store verifier securely (needed for token exchange)
 * 3. Send challenge in authorization request
 * 4. Send verifier in token exchange request
 *
 * @returns Complete PKCE pair with verifier, challenge, and method
 * @example
 * const { codeVerifier, codeChallenge, codeChallengeMethod } = generatePKCEPair()
 * // Store codeVerifier for later
 * // Include codeChallenge and codeChallengeMethod in authorization URL
 */ export function generatePKCEPair() {
    const codeVerifier = generateCodeVerifier();
    const codeChallenge = generateCodeChallenge(codeVerifier);
    return {
        codeChallenge,
        codeChallengeMethod: 'S256',
        codeVerifier
    };
}
/**
 * Base64URL encode without padding (RFC 7636 requirement)
 *
 * Converts a buffer to base64url format by:
 * 1. Base64 encoding
 * 2. Replacing + with -
 * 3. Replacing / with _
 * 4. Removing = padding
 *
 * This format is URL-safe and required by OAuth 2.0 PKCE spec.
 *
 * @param buffer - Buffer to encode
 * @returns Base64url encoded string (no padding)
 * @see https://datatracker.ietf.org/doc/html/rfc7636#appendix-A
 */ function base64UrlEncode(buffer) {
    return buffer.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}
